import process from 'node:process';

// ANSI color codes
export const COLORS = {
  reset: 0,
  bold: 1,
  red: 31,
  green: 32,
  yellow: 33,
  blue: 34,
  magenta: 35,
  cyan: 36,
  white: 37,
  gray: 90,
};

const FORCE_COLOR_VALUES = new Map([
  ['true', 1],
  ['false', 0],
  ['1', 1],
  ['2', 2],
  ['3', 3],
  ['0', 0],
]);

function hasFlag(argv, flag) {
  return argv.includes(flag);
}

/**
 * Detect the color support level of a stream (0 = none, 1 = basic,
 * 2 = 256 colors, 3 = truecolor).
 */
export function detectColorSupport(stream = process.stdout, argv = process.argv) {
  if (hasFlag(argv, '--no-color') || hasFlag(argv, '--no-colors')) return 0;

  const noColor = process.env.NO_COLOR;
  if (noColor !== undefined && noColor !== '') return 0;
  if (hasFlag(argv, '--color') || hasFlag(argv, '--colors')) return 1;

  const forceColor = process.env.FORCE_COLOR;
  if (forceColor !== undefined) {
    if (forceColor === '' ) return 1;
    if (FORCE_COLOR_VALUES.has(forceColor)) return FORCE_COLOR_VALUES.get(forceColor);
    return 1;
  }

  if (!stream || !stream.isTTY) return 0;

  if (process.platform === 'win32') {
    // modern Windows terminals (Windows Terminal, VS Code) support truecolor
    if (process.env.WT_SESSION || process.env.TERM_PROGRAM === 'vscode') return 3;
    return 1;
  }

  const term = process.env.TERM || '';
  if (term === 'dumb') return 0;

  if (/(?:-truecolor|-24bit)$/.test(term) || process.env.COLORTERM === 'truecolor' || process.env.COLORTERM === '24bit') {
    return 3;
  }

  if (term.includes('256')) return 2;

  if (process.env.CI) {
    // Many CI providers support colors
    if (['GITHUB_ACTIONS', 'GITLAB_CI', 'CIRCLECI', 'TRAVIS', 'BUILDKITE', 'TF_BUILD'].some((k) => process.env[k])) {
      return 1;
    }
  }

  return 1;
}
```

Wait, order matters. NO_COLOR should take precedence over FORCE_COLOR? Standard: command-line flag > FORCE_COLOR > NO_COLOR? Actually the NO_COLOR spec says it should be respected but explicit user config can override. Common implementation (supports-color): `--no-color` flag > FORCE_COLOR > NO_COLOR > TTY detection. Hmm let me recall supports-color source:

```js
