{
  "name": "color-cli",
  "version": "1.0.0",
  "description": "A Node.js CLI that detects terminal color support before printing colored text",
  "type": "module",
  "bin": {
    "color-cli": "./bin/cli.js"
  },
  "files": [
    "bin",
    "src"
  ],
  "scripts": {
    "start": "node ./bin/cli.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "cli",
    "terminal",
    "color",
    "ansi",
    "tty"
  ],
  "license": "MIT"
}

import process from 'node:process';

export const CODES = {
  reset: 0,
  bold: 1,
  dim: 2,
  underline: 4,
  red: 31,
  green: 32,
  yellow: 33,
  blue: 34,
  magenta: 35,
  cyan: 36,
  white: 37,
  gray: 90,
};

const FORCE_COLOR_LEVELS = new Map([
  ['', 1],
  ['true', 1],
  ['false', 0],
  ['1', 1],
  ['2', 2],
  ['3', 3],
  ['0', 0],
]);

const CI_PROVIDERS = [
  'GITHUB_ACTIONS',
  'GITLAB_CI',
  'CIRCLECI',
  'TRAVIS',
  'BUILDKITE',
  'TF_BUILD',
  'TEAMCITY_VERSION',
];

function hasFlag(argv, ...flags) {
  return flags.some((flag) => argv.includes(flag));
}

/**
 * Detect the color support level for a stream.
 *
 * Levels: 0 = no color, 1 = basic 16 colors, 2 = 256 colors,
 * 3 = 16 million (truecolor).
 *
 * Precedence: CLI flags > FORCE_COLOR > NO_COLOR > CI/TTY detection.
 *
 * @param {NodeJS.WriteStream} [stream] stream whose TTY status is checked
 * @param {string[]} [argv] argument list to scan for color flags
 * @returns {0 | 1 | 2 | 3}
 */
export function detectColorSupport(stream = process.stdout, argv = process.argv) {
  if (hasFlag(argv, '--no-color', '--no-colors')) return 0;
  if (hasFlag(argv, '--color', '--colors')) return 1;

  const forceColor = process.env.FORCE_COLOR;
  if (forceColor !== undefined) {
    const normalized = forceColor.toLowerCase();
    return FORCE_COLOR_LEVELS.has(normalized) ? FORCE_COLOR_LEVELS.get(normalized) : 1;
  }

  const noColor = process.env.NO_COLOR;
  if (noColor !== undefined && noColor !== '') return 0;

  if (!stream || stream.isTTY !== true) return 0;

  if (process.platform === 'win32') {
    if (process.env.WT_SESSION || process.env.TERM_PROGRAM === 'vscode') return 3;
    if (process.env.ANSICON || process.env.ConEmuANSI === 'ON') return 1;
    return 1;
  }

  const term = process.env.TERM ?? '';
  if (term === 'dumb') return 0;

  const colorterm = process.env.COLORTERM ?? '';
  if (colorterm === 'truecolor' || colorterm === '24bit') return 3;
  if (/(?:-truecolor|-24bit)$/.test(term)) return 3;

  if (term.includes('256')) return 2;

  if (CI_PROVIDERS.some((key) => process.env[key])) return 1;

  return 1;
}

/**
 * Build a styling function bound to a color support level. When the level is
 * 0 the function returns the text untouched, so callers never emit ANSI
 * escapes to unsupported terminals.
 *
 * @param {number} level color support level from {@link detectColorSupport}
 * @returns {(text: unknown, ...styles: (keyof typeof CODES)[]) => string}
 */
export function createStyler(level) {
  return (text, ...styles) => {
    const value = String(text);
    if (level < 1 || styles.length === 0) return value;

    const open = styles
      .map((style) => `\u001B[${CODES[style] ?? style}m`)
      .join('');

    return `${open}${value}\u001B[${CODES.reset}m`;
  };
}

export const supportsColor = detectColorSupport();

#!/usr/bin/env node
import process from 'node:process';
import { detectColorSupport, createStyler, CODES } from '../src/color-support.js';

const LEVEL_NAMES = {
  0: 'none',
  1: 'basic (16 colors)',
  2: '256 colors',
  3: 'truecolor (16 million)',
};

function printHelp() {
  const style = createStyler(1);
  process.stdout.write(
    [
      `${style('color-cli', 'green', 'bold')} - detect terminal color support`,
      '',
      `${style('Usage', 'bold')}`,
      '  color-cli [options] [text...]',
      '',
      `${style('Options', 'bold')}`,
      '  --check         Print the detected color support level only',
      '  --color         Force basic color output',
      '  --no-color      Disable colored output',
      '  -h, --help      Show this help',
      '',
      'Environment: NO_COLOR, FORCE_COLOR, TERM, COLORTERM',
      '',
    ].join('\n'),
  );
}

const argv = process.argv.slice(2);
const level = detectColorSupport(process.stdout, process.argv);
const style = createStyler(level);

if (argv.includes('-h') || argv.includes('--help')) {
  printHelp();
  process.exit(0);
}

if (argv.includes('--check')) {
  process.stdout.write(`color support: ${LEVEL_NAMES[level]} (level ${level})\n`);
  process.exit(0);
}

const text = argv.filter((arg) => !arg.startsWith('-')).join(' ') || 'Hello, color world!';

process.stdout.write(`${style(text, 'green', 'bold')}\n`);

if (level === 0) {
  process.stdout.write(
    `${style('(colors disabled)', 'gray')}\n`,
  );
}

export { CODES };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import process from 'node:process';
import { detectColorSupport, createStyler } from '../src/color-support.js';

const COLOR_ENV_KEYS = [
  'FORCE_COLOR',
  'NO_COLOR',
  'TERM',
  'COLORTERM',
  'WT_SESSION',
  'TERM_PROGRAM',
  'CI',
  'GITHUB_ACTIONS',
];

function withEnv(values, fn) {
  const saved = new Map();
  for (const key of COLOR_ENV_KEYS) {
    saved.set(key, process.env[key]);
    delete process.env[key];
  }
  Object.assign(process.env, values);
  try {
    return fn();
  } finally {
    for (const key of COLOR_ENV_KEYS) {
      const original = saved.get(key);
      if (original === undefined) delete process.env[key];
      else process.env[key] = original;
    }
  }
}

const TTY = { isTTY: true };
const PIPE = { isTTY: false };

test('returns 0 for a non-TTY stream', () => {
  withEnv({}, () => {
    assert.equal(detectColorSupport(PIPE, []), 0);
  });
});

test('returns basic color for a TTY', () => {
  withEnv({ TERM: 'xterm-256color' }, () => {
    assert.equal(detectColorSupport(TTY, []), 2);
  });
});

test('--no-color disables color even on a TTY', () => {
  withEnv({ TERM: 'xterm-256color' }, () => {
    assert.equal(detectColorSupport(TTY, ['node', 'cli', '--no-color']), 0);
  });
});

test('--color forces color through a pipe', () => {
  withEnv({}, () => {
    assert.equal(detectColorSupport(PIPE, ['node', 'cli', '--color']), 1);
  });
});

test('NO_COLOR disables color', () => {
  withEnv({ NO_COLOR: '1', TERM: 'xterm-256color' }, () => {
    assert.equal(detectColorSupport(TTY, []), 0);
  });
});

test('FORCE_COLOR wins over NO_COLOR', () => {
  withEnv({ FORCE_COLOR: '1', NO_COLOR: '1' }, () => {
    assert.equal(detectColorSupport(PIPE, []), 1);
  });
});

test('FORCE_COLOR=3 enables truecolor', () => {
  withEnv({ FORCE_COLOR: '3' }, () => {
    assert.equal(detectColorSupport(PIPE, []), 3);
  });
});

test('TERM=dumb disables color', () => {
  withEnv({ TERM: 'dumb' }, () => {
    assert.equal(detectColorSupport(TTY, []), 0);
  });
});

test('COLORTERM=truecolor enables truecolor', () => {
  withEnv({ TERM: 'xterm', COLORTERM: 'truecolor' }, () => {
    assert.equal(detectColorSupport(TTY, []), 3);
  });
});

test('CI provider enables color without a TTY', () => {
  withEnv({ CI: 'true', GITHUB_ACTIONS: 'true' }, () => {
    assert.equal(detectColorSupport(PIPE, []), 1);
  });
});

test('styler wraps text when color is supported', () => {
  const style = createStyler(1);
  assert.equal(style('hi', 'green'), '\u001B[32mhi\u001B[0m');
});

test('styler returns plain text at level 0', () => {
  const style = createStyler(0);
  assert.equal(style('hi', 'green', 'bold'), 'hi');
});

